  /// <summary>
  /// The requests of the protocol, implemented by the server.
  /// </summary>
  public interface IProtocolRequestHandler {
    /// <summary>
    /// "files/register": Registers a file opened by the client: the project containing the file is discovered (e.g. a
    /// directory with a vs-chromium-project.txt file) and indexed.
    /// </summary>
    ValueTask FilesRegisterAsync(FilesRegisterParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "files/unregister": Unregisters a file registered with "files/register" (e.g. the file was closed).
    /// </summary>
    ValueTask FilesUnregisterAsync(FilesUnregisterParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "files/extracts": Extracts of the text of a file around spans of text.
    /// </summary>
    ValueTask<FileExtractsResult> FilesExtractsAsync(FileExtractsParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "index/pause": Pauses indexing: file system changes are not processed until "index/resume".
    /// </summary>
    ValueTask IndexPauseAsync(CancellationToken cancellationToken);

    /// <summary>
    /// "index/resume": Resumes indexing (after "index/pause", or when the server paused itself).
    /// </summary>
    ValueTask IndexResumeAsync(CancellationToken cancellationToken);

    /// <summary>
    /// "index/statistics": Statistics of the index (including the arena statistics: a walk of the file contents).
    /// </summary>
    ValueTask<IndexStatistics> IndexStatisticsAsync(IndexStatisticsParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "index/status": State of the index without the arena statistics: cheap, for frequent refreshes.
    /// </summary>
    ValueTask<IndexStatus> IndexStatusAsync(CancellationToken cancellationToken);

    /// <summary>
    /// "index/clearCache": Deletes the persistent index cache of all the projects (see "project/clearCache" for a
    /// project): the same deletion as "tree/refresh" (Rebuild index), without the rescan. The current
    /// index stays in use (the contents loaded from the cache stay readable). The cache is written
    /// again by the save policy: the index is marked as changed, saved once it settles (30 s), or
    /// after the load in progress, if any. A server stopped before that save starts cold the next
    /// time.
    /// </summary>
    ValueTask<ClearCacheResult> IndexClearCacheAsync(CancellationToken cancellationToken);

    /// <summary>
    /// "index/details": Details of all the projects.
    /// </summary>
    ValueTask<IndexDetails> IndexDetailsAsync(DetailsParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "project/setOptions": Changes the options of a project, at any time (also before the project is loaded). Options are
    /// kept for the lifetime of the server process: clients send them again after starting a server.
    /// </summary>
    ValueTask ProjectSetOptionsAsync(SetProjectOptionsParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "project/details": Details of a project: statistics of its files and configuration.
    /// </summary>
    ValueTask<ProjectDetails> ProjectDetailsAsync(ProjectDetailsParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "project/rebuild": Rebuilds the index of a project: deletes its index cache, rescans the project and reads all its
    /// files again (the other projects keep their tree and contents). Asynchronous: the progress is
    /// reported by the usual notifications ("index/scanStarted", ..., "index/loaded").
    /// </summary>
    ValueTask ProjectRebuildAsync(ProjectPathParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "project/clearCache": Deletes the index cache of a project, without rescan: the current index stays in use, and is
    /// saved to the cache again by the save policy (see "index/clearCache").
    /// </summary>
    ValueTask<ClearCacheResult> ProjectClearCacheAsync(ProjectPathParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "project/directorySizes": The size on disk of a directory of a project and of its children (disk usage view), from the
    /// scan of the project (no disk access) and the file database (searchable files). The sizes of all
    /// the directories of the project are computed by the first request for a snapshot (one pass) and
    /// kept until the snapshot changes. The directories and files excluded by "[SourceExplorer.ignore]"
    /// are listed with a directory listing of the requested directory only.
    /// </summary>
    ValueTask<DirectorySizes> ProjectDirectorySizesAsync(DirectoryPathParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "project/measureDirectory": Starts the measurement of a directory excluded from the index (enumeration of its files in the
    /// background, never part of the scan), or returns its progress or result (call again to poll).
    /// Results are kept for the lifetime of the server.
    /// </summary>
    ValueTask<DirectoryMeasurement> ProjectMeasureDirectoryAsync(MeasureDirectoryParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "project/cancelMeasure": Cancels the measurement of a directory, if running.
    /// </summary>
    ValueTask<DirectoryMeasurement> ProjectCancelMeasureAsync(DirectoryPathParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "project/addIgnorePattern": Adds a pattern to a section of the project file (`vs-chromium-project.txt`), if not already
    /// present (the formatting, encoding and line endings of the file are kept). The change of the
    /// project file makes the server rescan the project. Recoverable error if the project has no
    /// editable project file (e.g. Chromium projects) or the pattern is invalid.
    /// </summary>
    ValueTask<AddIgnorePatternResult> ProjectAddIgnorePatternAsync(AddIgnorePatternParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "search/code": Searches the contents of the indexed files.
    /// </summary>
    ValueTask<SearchCodeResult> SearchCodeAsync(SearchParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "search/paths": Searches the paths of the indexed files ("text" is matched against names or relative paths).
    /// </summary>
    ValueTask<SearchPathsResult> SearchPathsAsync(SearchParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "server/initialize": First request sent by a client: exchanges versions.
    /// </summary>
    ValueTask<InitializeResult> ServerInitializeAsync(InitializeParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "server/statistics": Process, memory and index statistics.
    /// </summary>
    ValueTask<ServerStatistics> ServerStatisticsAsync(ServerStatisticsParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "server/history": History of the server (charts): cheap samples every 10 s, last 2 hours.
    /// </summary>
    ValueTask<ServerHistory> ServerHistoryAsync(ServerHistoryParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "tree/get": The projects known to the server.
    /// </summary>
    ValueTask<FileSystemTree> TreeGetAsync(TreeParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "tree/entries": The entries of a directory of a project.
    /// </summary>
    ValueTask<DirectoryEntries> TreeEntriesAsync(TreeEntriesParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "tree/entriesMultiple": The entries of several directories of a project.
    /// </summary>
    ValueTask<DirectoryEntriesList> TreeEntriesMultipleAsync(TreeEntriesMultipleParams parameters, CancellationToken cancellationToken);

    /// <summary>
    /// "tree/refresh": Rescans the file system (e.g. after changes not reported by the file system watcher).
    /// </summary>
    ValueTask TreeRefreshAsync(CancellationToken cancellationToken);

    /// <summary>
    /// "tree/directoryDetails": Statistics of the files of a directory (with "files by extension" and "large files" lists).
    /// </summary>
    ValueTask<DirectoryDetails> TreeDirectoryDetailsAsync(DirectoryDetailsParams parameters, CancellationToken cancellationToken);
  }

  /// <summary>
  /// Dispatches the requests of the protocol to an <see cref="IProtocolRequestHandler"/>.
  /// </summary>
  public static class ProtocolDispatcher {
    /// <summary>
    /// True if <paramref name="method"/> is a request of the protocol.
    /// </summary>
    public static bool IsRequest(string method) => method switch {
      ProtocolMethods.FilesRegister => true,
      ProtocolMethods.FilesUnregister => true,
      ProtocolMethods.FilesExtracts => true,
      ProtocolMethods.IndexPause => true,
      ProtocolMethods.IndexResume => true,
      ProtocolMethods.IndexStatistics => true,
      ProtocolMethods.IndexStatus => true,
      ProtocolMethods.IndexClearCache => true,
      ProtocolMethods.IndexDetails => true,
      ProtocolMethods.ProjectSetOptions => true,
      ProtocolMethods.ProjectDetails => true,
      ProtocolMethods.ProjectRebuild => true,
      ProtocolMethods.ProjectClearCache => true,
      ProtocolMethods.ProjectDirectorySizes => true,
      ProtocolMethods.ProjectMeasureDirectory => true,
      ProtocolMethods.ProjectCancelMeasure => true,
      ProtocolMethods.ProjectAddIgnorePattern => true,
      ProtocolMethods.SearchCode => true,
      ProtocolMethods.SearchPaths => true,
      ProtocolMethods.ServerInitialize => true,
      ProtocolMethods.ServerStatistics => true,
      ProtocolMethods.ServerHistory => true,
      ProtocolMethods.TreeGet => true,
      ProtocolMethods.TreeEntries => true,
      ProtocolMethods.TreeEntriesMultiple => true,
      ProtocolMethods.TreeRefresh => true,
      ProtocolMethods.TreeDirectoryDetails => true,
      _ => false,
    };

    /// <summary>
    /// Deserializes the parameters of the request <paramref name="method"/>, calls the handler, and
    /// returns the serialized result (null for requests without result). Throws <see
    /// cref="ProtocolMethodNotFoundException"/> for unknown methods, <see
    /// cref="ProtocolInvalidParamsException"/> for invalid parameters.
    /// </summary>
    public static async ValueTask<JsonElement?> DispatchRequestAsync(IProtocolRequestHandler handler, string method, JsonElement? parameters, CancellationToken cancellationToken) {
      switch (method) {
        case ProtocolMethods.FilesRegister: {
          await handler.FilesRegisterAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.FilesRegisterParams), cancellationToken).ConfigureAwait(false);
          return null;
        }
        case ProtocolMethods.FilesUnregister: {
          await handler.FilesUnregisterAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.FilesUnregisterParams), cancellationToken).ConfigureAwait(false);
          return null;
        }
        case ProtocolMethods.FilesExtracts: {
          var result = await handler.FilesExtractsAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.FileExtractsParams), cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.FileExtractsResult);
        }
        case ProtocolMethods.IndexPause: {
          await handler.IndexPauseAsync(cancellationToken).ConfigureAwait(false);
          return null;
        }
        case ProtocolMethods.IndexResume: {
          await handler.IndexResumeAsync(cancellationToken).ConfigureAwait(false);
          return null;
        }
        case ProtocolMethods.IndexStatistics: {
          var result = await handler.IndexStatisticsAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.IndexStatisticsParams), cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.IndexStatistics);
        }
        case ProtocolMethods.IndexStatus: {
          var result = await handler.IndexStatusAsync(cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.IndexStatus);
        }
        case ProtocolMethods.IndexClearCache: {
          var result = await handler.IndexClearCacheAsync(cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.ClearCacheResult);
        }
        case ProtocolMethods.IndexDetails: {
          var result = await handler.IndexDetailsAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.DetailsParams), cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.IndexDetails);
        }
        case ProtocolMethods.ProjectSetOptions: {
          await handler.ProjectSetOptionsAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.SetProjectOptionsParams), cancellationToken).ConfigureAwait(false);
          return null;
        }
        case ProtocolMethods.ProjectDetails: {
          var result = await handler.ProjectDetailsAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.ProjectDetailsParams), cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.ProjectDetails);
        }
        case ProtocolMethods.ProjectRebuild: {
          await handler.ProjectRebuildAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.ProjectPathParams), cancellationToken).ConfigureAwait(false);
          return null;
        }
        case ProtocolMethods.ProjectClearCache: {
          var result = await handler.ProjectClearCacheAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.ProjectPathParams), cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.ClearCacheResult);
        }
        case ProtocolMethods.ProjectDirectorySizes: {
          var result = await handler.ProjectDirectorySizesAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.DirectoryPathParams), cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.DirectorySizes);
        }
        case ProtocolMethods.ProjectMeasureDirectory: {
          var result = await handler.ProjectMeasureDirectoryAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.MeasureDirectoryParams), cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.DirectoryMeasurement);
        }
        case ProtocolMethods.ProjectCancelMeasure: {
          var result = await handler.ProjectCancelMeasureAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.DirectoryPathParams), cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.DirectoryMeasurement);
        }
        case ProtocolMethods.ProjectAddIgnorePattern: {
          var result = await handler.ProjectAddIgnorePatternAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.AddIgnorePatternParams), cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.AddIgnorePatternResult);
        }
        case ProtocolMethods.SearchCode: {
          var result = await handler.SearchCodeAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.SearchParams), cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.SearchCodeResult);
        }
        case ProtocolMethods.SearchPaths: {
          var result = await handler.SearchPathsAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.SearchParams), cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.SearchPathsResult);
        }
        case ProtocolMethods.ServerInitialize: {
          var result = await handler.ServerInitializeAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.InitializeParams), cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.InitializeResult);
        }
        case ProtocolMethods.ServerStatistics: {
          var result = await handler.ServerStatisticsAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.ServerStatisticsParams), cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.ServerStatistics);
        }
        case ProtocolMethods.ServerHistory: {
          var result = await handler.ServerHistoryAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.ServerHistoryParams), cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.ServerHistory);
        }
        case ProtocolMethods.TreeGet: {
          var result = await handler.TreeGetAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.TreeParams), cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.FileSystemTree);
        }
        case ProtocolMethods.TreeEntries: {
          var result = await handler.TreeEntriesAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.TreeEntriesParams), cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.DirectoryEntries);
        }
        case ProtocolMethods.TreeEntriesMultiple: {
          var result = await handler.TreeEntriesMultipleAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.TreeEntriesMultipleParams), cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.DirectoryEntriesList);
        }
        case ProtocolMethods.TreeRefresh: {
          await handler.TreeRefreshAsync(cancellationToken).ConfigureAwait(false);
          return null;
        }
        case ProtocolMethods.TreeDirectoryDetails: {
          var result = await handler.TreeDirectoryDetailsAsync(DeserializeParameters(parameters, ProtocolJsonContext.Default.DirectoryDetailsParams), cancellationToken).ConfigureAwait(false);
          return JsonSerializer.SerializeToElement(result, ProtocolJsonContext.Default.DirectoryDetails);
        }
        default:
          throw new ProtocolMethodNotFoundException(method);
      }
    }

    private static T DeserializeParameters<T>(JsonElement? parameters, JsonTypeInfo<T> typeInfo) {
      if (parameters is not { ValueKind: JsonValueKind.Object } value) {
        throw new ProtocolInvalidParamsException("The parameters must be an object");
      }
      try {
        return value.Deserialize(typeInfo) ?? throw new ProtocolInvalidParamsException("Missing parameters");
      }
      catch (JsonException e) {
        throw new ProtocolInvalidParamsException(e.Message, e);
      }
    }
  }

  /// <summary>
  /// Sends the notifications of the protocol (server to client): serializes their parameters.
  /// </summary>
  public abstract class ProtocolNotificationSender {
    protected abstract void SendNotification(string method, JsonElement? parameters);

    /// <summary>
    /// "index/stateChanged": The indexing state changed.
    /// </summary>
    public void IndexStateChanged(IndexStateChangedParams parameters) =>
      SendNotification(ProtocolMethods.IndexStateChanged, JsonSerializer.SerializeToElement(parameters, ProtocolJsonContext.Default.IndexStateChangedParams));

    /// <summary>
    /// "index/scanStarted": A file system scan started.
    /// </summary>
    public void IndexScanStarted(OperationStartedParams parameters) =>
      SendNotification(ProtocolMethods.IndexScanStarted, JsonSerializer.SerializeToElement(parameters, ProtocolJsonContext.Default.OperationStartedParams));

    /// <summary>
    /// "index/scanFinished": A file system scan finished.
    /// </summary>
    public void IndexScanFinished(ScanFinishedParams parameters) =>
      SendNotification(ProtocolMethods.IndexScanFinished, JsonSerializer.SerializeToElement(parameters, ProtocolJsonContext.Default.ScanFinishedParams));

    /// <summary>
    /// "index/loading": Loading of file contents started.
    /// </summary>
    public void IndexLoading(OperationStartedParams parameters) =>
      SendNotification(ProtocolMethods.IndexLoading, JsonSerializer.SerializeToElement(parameters, ProtocolJsonContext.Default.OperationStartedParams));

    /// <summary>
    /// "index/loadingProgress": Progress of the loading of file contents (sent periodically during the loading).
    /// </summary>
    public void IndexLoadingProgress(OperationStartedParams parameters) =>
      SendNotification(ProtocolMethods.IndexLoadingProgress, JsonSerializer.SerializeToElement(parameters, ProtocolJsonContext.Default.OperationStartedParams));

    /// <summary>
    /// "index/loaded": Loading of file contents finished: the index is up to date.
    /// </summary>
    public void IndexLoaded(FilesLoadedParams parameters) =>
      SendNotification(ProtocolMethods.IndexLoaded, JsonSerializer.SerializeToElement(parameters, ProtocolJsonContext.Default.FilesLoadedParams));

    /// <summary>
    /// "index/progress": Progress of a long operation, for display.
    /// </summary>
    public void IndexProgress(ProgressParams parameters) =>
      SendNotification(ProtocolMethods.IndexProgress, JsonSerializer.SerializeToElement(parameters, ProtocolJsonContext.Default.ProgressParams));
  }

  /// <summary>
  /// An error of a request, reported to the client with a JSON-RPC error code.
  /// </summary>
  public class ProtocolException : Exception {
    public ProtocolException(int code, string message, Exception? innerException = null) : base(message, innerException) {
      Code = code;
    }

    /// <summary>
    /// The JSON-RPC error code.
    /// </summary>
    public int Code { get; }
  }

  public sealed class ProtocolMethodNotFoundException : ProtocolException {
    public const int ErrorCode = -32601;

    public ProtocolMethodNotFoundException(string method) : base(ErrorCode, $"Unknown method \"{method}\"") {
      Method = method;
    }

    public string Method { get; }
  }

  public sealed class ProtocolInvalidParamsException : ProtocolException {
    public const int ErrorCode = -32602;

    public ProtocolInvalidParamsException(string message, Exception? innerException = null) : base(ErrorCode, "Invalid parameters: " + message, innerException) { }
  }

